// Rust/TypeScript parity: run the shared vectors through the TS port.
// The vectors are generated by crates/ch_math/tests/vectors.rs; this file only
// reads them, so the two suites can never silently drift apart.
import { describe, it, expect } from "vitest";
import vectors from "../../crates/ch_math/tests/vectors/portfolio.json";
import {
  computePortfolioCredit,
  totalCredit,
  MarginAsRiskModel,
  StressedRiskModel,
  HedgeBreakModel,
  hedgeBreakLoss,
  PortfolioError,
  PortfolioLeg,
  AssetRisk,
  MAX_ASSETS,
} from "./portfolio";

const doc: any = vectors;

function rhoFn(table: [number, number, number][]) {
  return (a: number, b: number): bigint => {
    const [x, y] = a < b ? [a, b] : [b, a];
    const t = table.find((r) => r[0] === x && r[1] === y);
    return BigInt(t ? t[2] : 0);
  };
}

function modelOf(m: any) {
  if (m.kind === "margin_as_risk") return { model: new MarginAsRiskModel(rhoFn(m.rho)), stressed: null, hedgeBreak: null };
  const assets: AssetRisk[] = [];
  for (const [k, v] of Object.entries(m.assets as Record<string, number[]>)) {
    assets[Number(k)] = { shockBps: v[0], gapBps: v[1], basisBps: v[2] };
  }
  const scenarios = (m.scenarios as [number, number][][]).map((sc) => {
    const v = new Array(MAX_ASSETS).fill(0);
    for (const [a, mv] of sc) v[a] = mv;
    return v;
  });
  const s = new StressedRiskModel(assets, rhoFn(m.rho), m.corr_stress_ppm, m.basis_decorr_ppm, scenarios);
  if (typeof m.hedge_break_bps === "number") {
    const hb = new HedgeBreakModel(s, m.hedge_break_bps);
    return { model: hb, stressed: s, hedgeBreak: hb };
  }
  return { model: s, stressed: s, hedgeBreak: null };
}

describe("shared parity vectors (crates/ch_math/tests/vectors/portfolio.json)", () => {
  it("has the expected number of cases", () => {
    expect(doc.cases.length).toBeGreaterThanOrEqual(10);
  });

  for (const c of doc.cases) {
    it(c.name, () => {
      const { model, stressed, hedgeBreak } = modelOf(doc.models[c.model]);
      const legs: PortfolioLeg[] = c.legs.map((l: any) => ({
        venueIndex: l.venue,
        asset: l.asset,
        isLong: l.long,
        notional: BigInt(l.notional),
        initialMargin: BigInt(l.im),
        maintenanceMargin: BigInt(l.mm),
      }));
      const params = {
        haircutBps: c.params.haircut_bps,
        maxCreditPerUser: BigInt(c.params.max_credit_per_user),
        maxCreditBpsOfIm: c.params.max_credit_bps_of_im,
        capAtImMinusMm: c.params.cap_at_im_minus_mm,
      };
      if (c.expect.error) {
        let err: unknown;
        try {
          computePortfolioCredit(legs, model, params);
        } catch (e) {
          err = e;
        }
        expect(err).toBeInstanceOf(PortfolioError);
        expect((err as PortfolioError).code).toBe(c.expect.error);
        return;
      }
      const r = computePortfolioCredit(legs, model, params);
      const got: Record<string, unknown> = {
        sum_standalone_risk: r.sumStandaloneRisk.toString(),
        portfolio_risk: r.portfolioRisk.toString(),
        hedge_benefit_ppm: r.hedgeBenefitPpm,
        sum_initial_margin: r.sumInitialMargin.toString(),
        total_before_leg_caps: r.totalBeforeLegCaps.toString(),
        leg_credit: r.legCredit.map(String),
        total: totalCredit(r).toString(),
      };
      if (hedgeBreak) {
        got.parametric_risk = hedgeBreak.inner.parametricRisk(legs).toString();
        got.scenario_risk = hedgeBreak.scenarioRisk(legs).toString();
        got.hedge_break_loss = hedgeBreakLoss(hedgeBreak.inner, legs, hedgeBreak.hedgeBreakBps).toString();
      } else if (stressed) {
        got.parametric_risk = stressed.parametricRisk(legs).toString();
        got.scenario_risk = stressed.scenarioRisk(legs).toString();
      }
      expect(got).toEqual(c.expect);
    });
  }
});
